<?php
declare(strict_types=1);

const MEDIA_IMAGE_WIDTHS=[320,480,768,1024,1440,1920];
const MEDIA_UPLOAD_MAX_BYTES=52428800;
const MEDIA_POSTER_MAX_BYTES=10485760;

function media_upload_root():string{return dirname(__DIR__).'/uploads/media';}
function media_url(string $path):string{return '/uploads/media/'.ltrim(str_replace('\\','/',$path),'/');}
function media_video_url(int $assetId,int $versionId,string $path):string{if(str_starts_with($path,'../../assets/media/'))return '/assets/media/'.rawurlencode(basename($path));return '/media-stream.php?asset='.rawurlencode((string)$assetId).'&version='.rawurlencode((string)$versionId);}
function media_capabilities():array{return ['imagick'=>extension_loaded('imagick'),'gd'=>extension_loaded('gd'),'webp'=>function_exists('imagewebp'),'upload_max'=>ini_get('upload_max_filesize'),'post_max'=>ini_get('post_max_size'),'memory_limit'=>ini_get('memory_limit')];}
function media_mime_extension(string $mime):?string{return ['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp','video/mp4'=>'mp4','video/webm'=>'webm'][$mime]??null;}
function media_safe_file(array $file):array{if(($file['error']??UPLOAD_ERR_NO_FILE)!==UPLOAD_ERR_OK)throw new RuntimeException('upload_failed');if(!is_file((string)($file['tmp_name']??''))||($file['size']??0)<1||($file['size']??0)>MEDIA_UPLOAD_MAX_BYTES)throw new RuntimeException('file_too_large');$mime=(new finfo(FILEINFO_MIME_TYPE))->file($file['tmp_name']);$extension=media_mime_extension($mime?:'');if($extension===null)throw new RuntimeException('unsupported_or_invalid_file');$given=strtolower((string)pathinfo((string)($file['name']??''),PATHINFO_EXTENSION));if($given!==$extension)throw new RuntimeException('extension_mime_mismatch');return [$mime,str_starts_with($mime,'video/')?'video':'image',$extension];}
function media_image_info(string $file):array{$i=@getimagesize($file);return $i?[(int)$i[0],(int)$i[1]]:[null,null];}
function media_mkdir(string $dir):void{if(!is_dir($dir)&&!mkdir($dir,0755,true)&&!is_dir($dir))throw new RuntimeException('storage_unavailable');}
function media_remove_tree(string $dir):void{if(!is_dir($dir))return;foreach(scandir($dir)?:[] as $item){if($item==='.'||$item==='..')continue;$path=$dir.'/'.$item;if(is_dir($path))media_remove_tree($path);else @unlink($path);}@rmdir($dir);}
function media_create(PDO $db,array $file,?int $replaceAsset=null):array{[$mime,$kind,$extension]=media_safe_file($file);$now=gmdate('c');$assetUuid=bin2hex(random_bytes(16));$versionUuid=bin2hex(random_bytes(16));$checksum=hash_file('sha256',$file['tmp_name']);[$w,$h]=$kind==='image'?media_image_info($file['tmp_name']):[null,null];$asset=$replaceAsset?$db->prepare('SELECT * FROM media_assets WHERE id=?'):null;if($asset){$asset->execute([$replaceAsset]);$existing=$asset->fetch();if(!$existing)throw new RuntimeException('asset_not_found');if($existing['kind']!==$kind)throw new RuntimeException('asset_type_mismatch');$assetId=$replaceAsset;$assetUuid=$existing['asset_uuid'];$db->prepare('UPDATE media_assets SET title=?,original_name=?,mime_type=?,byte_size=?,width=?,height=?,checksum=?,processing_status="processing",updated_at=? WHERE id=?')->execute([$file['name'],$file['name'],$mime,$file['size'],$w,$h,$checksum,$now,$assetId]);}else{$q=$db->prepare('INSERT INTO media_assets(asset_uuid,kind,title,original_name,mime_type,byte_size,width,height,checksum,processing_status,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,"processing",?,?)');$q->execute([$assetUuid,$kind,pathinfo($file['name'],PATHINFO_FILENAME),$file['name'],$mime,$file['size'],$w,$h,$checksum,$now,$now]);$assetId=(int)$db->lastInsertId();}$relative=$assetUuid.'/'.$versionUuid.'/original/file.'.$extension;$destination=media_upload_root().'/'.$relative;media_mkdir(dirname($destination));if(!move_uploaded_file($file['tmp_name'],$destination))throw new RuntimeException('storage_write_failed');$q=$db->prepare('INSERT INTO media_versions(asset_id,version_uuid,original_path,mime_type,byte_size,width,height,checksum,processing_status,created_at) VALUES(?,?,?,?,?,?,?,?,"processing",?)');$q->execute([$assetId,$versionUuid,$relative,$mime,$file['size'],$w,$h,$checksum,$now]);$versionId=(int)$db->lastInsertId();try{if($kind==='image')media_generate_images($db,$versionId,$relative,$mime,$w,$h);$db->prepare('UPDATE media_versions SET processing_status="ready" WHERE id=?')->execute([$versionId]);$db->prepare('UPDATE media_assets SET active_version_id=?,processing_status="ready",updated_at=? WHERE id=?')->execute([$versionId,$now,$assetId]);}catch(Throwable $e){$db->prepare('UPDATE media_versions SET processing_status="error",error_message=? WHERE id=?')->execute([$e->getMessage(),$versionId]);$db->prepare('UPDATE media_assets SET processing_status="error",updated_at=? WHERE id=?')->execute([$now,$assetId]);throw $e;}return media_asset($db,$assetId);}
function media_generate_images(PDO $db,int $versionId,string $relative,string $mime,?int $w,?int $h):void{$source=media_upload_root().'/'.$relative;if(!$w||!$h||!extension_loaded('gd'))return;$make=match($mime){'image/jpeg'=>'imagecreatefromjpeg','image/png'=>'imagecreatefrompng','image/webp'=>function($p){return function_exists('imagecreatefromwebp')?imagecreatefromwebp($p):false;}};$img=$make($source);if(!$img)throw new RuntimeException('image_processing_failed');$base=dirname(dirname($relative));foreach(MEDIA_IMAGE_WIDTHS as $target){if($target>$w)continue;$height=(int)round($h*$target/$w);$out=imagecreatetruecolor($target,$height);imagealphablending($out,false);imagesavealpha($out,true);$transparent=imagecolorallocatealpha($out,0,0,0,127);imagefill($out,0,0,$transparent);imagecopyresampled($out,$img,0,0,0,0,$target,$height,$w,$h);$dir=media_upload_root().'/'.$base.'/responsive';media_mkdir($dir);$path=$base.'/responsive/'.$target.'.jpg';imagejpeg($out,media_upload_root().'/'.$path,84);imagedestroy($out);$db->prepare('INSERT OR REPLACE INTO media_derivatives(version_id,derivative_kind,width,height,format,path,byte_size,created_at) VALUES(?,?,?,?,?,?,?,?)')->execute([$versionId,'responsive',$target,$height,'jpeg',$path,filesize(media_upload_root().'/'.$path),gmdate('c')]);}imagedestroy($img);}
function media_poster_rows(PDO $db,int $versionId):array{$q=$db->prepare('SELECT p.id,p.poster_uuid,p.timestamp_seconds,p.created_at,v.id variant_id,v.variant_key,v.width,v.height,v.format,v.mime_type,v.path,v.size_bytes,v.checksum FROM media_posters p LEFT JOIN media_poster_variants v ON v.poster_id=p.id WHERE p.video_version_id=? ORDER BY p.id DESC,v.width DESC,v.format ASC');$q->execute([$versionId]);$posters=[];foreach($q->fetchAll() as $row){$id=(int)$row['id'];if(!isset($posters[$id]))$posters[$id]=['id'=>$id,'posterUuid'=>$row['poster_uuid'],'timestamp'=>(float)$row['timestamp_seconds'],'createdAt'=>$row['created_at'],'variants'=>[]];if($row['variant_id']!==null)$posters[$id]['variants'][]=['key'=>$row['variant_key'],'format'=>$row['format'],'mimeType'=>$row['mime_type'],'width'=>(int)$row['width'],'height'=>(int)$row['height'],'path'=>$row['path'],'sizeBytes'=>(int)$row['size_bytes'],'checksum'=>$row['checksum'],'src'=>media_url($row['path'])];}return array_values($posters);}
function media_asset(PDO $db,int $id):array{$q=$db->prepare('SELECT a.*,v.original_path,v.version_uuid,v.processing_status version_processing_status FROM media_assets a LEFT JOIN media_versions v ON v.id=a.active_version_id WHERE a.id=?');$q->execute([$id]);$a=$q->fetch();if(!$a)throw new RuntimeException('asset_not_found');$q=$db->prepare('SELECT * FROM media_derivatives WHERE version_id=? ORDER BY width');$q->execute([$a['active_version_id']]);$a['derivatives']=$q->fetchAll();$a['url']=$a['kind']==='video'?media_video_url((int)$a['id'],(int)$a['active_version_id'],(string)$a['original_path']):media_url($a['original_path']);$a['posters']=$a['kind']==='video'?media_poster_rows($db,(int)$a['active_version_id']):[];if($a['posters']){$variants=$a['posters'][0]['variants'];$jpeg=array_values(array_filter($variants,fn($v)=>$v['format']==='jpeg'));$a['poster']=$jpeg[0]??$variants[0]??null;}else $a['poster']=null;return $a;}
function media_list(PDO $db):array{$rows=$db->query('SELECT id FROM media_assets WHERE archived_at IS NULL ORDER BY id DESC')->fetchAll();return array_map(fn($r)=>media_asset($db,(int)$r['id']),$rows);}
function media_poster_source(string $file,string $mime):array{if(extension_loaded('imagick')){$image=new Imagick($file);$image->setImageColorspace(Imagick::COLORSPACE_SRGB);return ['engine'=>'imagick','image'=>$image];}if(!extension_loaded('gd'))throw new RuntimeException('image_engine_unavailable');$image=$mime==='image/jpeg'?@imagecreatefromjpeg($file):@imagecreatefrompng($file);if(!$image)throw new RuntimeException('frame_decode_failed');return ['engine'=>'gd','image'=>$image];}
function media_write_poster_variant(array $source,int $sourceWidth,int $sourceHeight,int $width,int $height,string $format,string $path):void{if($source['engine']==='imagick'){$image=clone $source['image'];$image->resizeImage($width,$height,Imagick::FILTER_LANCZOS,1);$image->setImageFormat($format==='jpeg'?'jpeg':'webp');$image->setImageCompressionQuality(86);$image->writeImage($path);$image->clear();return;}$out=imagecreatetruecolor($width,$height);$background=imagecolorallocate($out,0,0,0);imagefill($out,0,0,$background);imagecopyresampled($out,$source['image'],0,0,0,0,$width,$height,$sourceWidth,$sourceHeight);$ok=$format==='jpeg'?imagejpeg($out,$path,86):(function_exists('imagewebp')&&imagewebp($out,$path,84));imagedestroy($out);if(!$ok)throw new RuntimeException('poster_write_failed');}
function media_create_poster(PDO $db,int $assetId,int $versionId,float $timestamp,array $file):array{if(!is_finite($timestamp)||$timestamp<0)throw new RuntimeException('invalid_timestamp');if(($file['error']??UPLOAD_ERR_NO_FILE)!==UPLOAD_ERR_OK||!is_file((string)($file['tmp_name']??''))||($file['size']??0)<1||($file['size']??0)>MEDIA_POSTER_MAX_BYTES)throw new RuntimeException('invalid_frame');$mime=(new finfo(FILEINFO_MIME_TYPE))->file($file['tmp_name']);if(!in_array($mime,['image/jpeg','image/png'],true))throw new RuntimeException('invalid_frame_type');$info=@getimagesize($file['tmp_name']);if(!$info||$info[0]<1||$info[1]<1)throw new RuntimeException('invalid_frame');$q=$db->prepare('SELECT a.asset_uuid,a.kind,v.id,v.version_uuid FROM media_assets a JOIN media_versions v ON v.asset_id=a.id WHERE a.id=? AND v.id=? AND v.processing_status="ready"');$q->execute([$assetId,$versionId]);$video=$q->fetch();if(!$video||$video['kind']!=='video')throw new RuntimeException('invalid_video_version');$uuid=bin2hex(random_bytes(16));$now=gmdate('c');$dir=media_upload_root().'/'.$video['asset_uuid'].'/'.$video['version_uuid'].'/posters/'.$uuid;$source=null;$db->beginTransaction();try{media_mkdir($dir);$source=media_poster_source($file['tmp_name'],$mime);$db->prepare('INSERT INTO media_posters(video_asset_id,video_version_id,poster_uuid,timestamp_seconds,source_width,source_height,created_at) VALUES(?,?,?,?,?,?,?)')->execute([$assetId,$versionId,$uuid,$timestamp,$info[0],$info[1],$now]);$posterId=(int)$db->lastInsertId();$widths=array_values(array_filter(MEDIA_IMAGE_WIDTHS,fn($width)=>$width<=$info[0]));if(!$widths)$widths=[$info[0]];$variants=[];foreach($widths as $width){$height=(int)round($info[1]*$width/$info[0]);foreach(['jpeg','webp'] as $format){if($format==='webp'&&!function_exists('imagewebp')&&!extension_loaded('imagick'))continue;$fileName=$width.'.'.($format==='jpeg'?'jpg':'webp');$path=$dir.'/'.$fileName;media_write_poster_variant($source,$info[0],$info[1],$width,$height,$format,$path);if(!is_file($path)||filesize($path)<1)throw new RuntimeException('poster_write_failed');$relative=substr($path,strlen(media_upload_root())+1);$mimeType=$format==='jpeg'?'image/jpeg':'image/webp';$db->prepare('INSERT INTO media_poster_variants(poster_id,variant_key,width,height,format,mime_type,path,size_bytes,checksum,created_at) VALUES(?,?,?,?,?,?,?,?,?,?)')->execute([$posterId,(string)$width,$width,$height,$format,$mimeType,$relative,filesize($path),hash_file('sha256',$path),$now]);$variants[]=['key'=>(string)$width,'format'=>$format,'mimeType'=>$mimeType,'width'=>$width,'height'=>$height,'src'=>media_url($relative)];}}$db->commit();if($source&&$source['engine']==='imagick')$source['image']->clear();if($source&&$source['engine']==='gd')imagedestroy($source['image']);$jpeg=array_values(array_filter($variants,fn($variant)=>$variant['format']==='jpeg'));return ['id'=>$posterId,'mediaAssetId'=>$assetId,'mediaVersionId'=>$versionId,'posterUuid'=>$uuid,'timestamp'=>$timestamp,'width'=>$info[0],'height'=>$info[1],'src'=>($jpeg[count($jpeg)-1]??$variants[count($variants)-1])['src'],'variants'=>$variants];}catch(Throwable $e){if($source&&$source['engine']==='imagick')$source['image']->clear();if($source&&$source['engine']==='gd')imagedestroy($source['image']);if($db->inTransaction())$db->rollBack();media_remove_tree($dir);throw $e;}}
